class Solution:
    def characterReplacement(self, s: str, k: int) -> int:
        counts=[0]*26;left=0;max_freq=0;best=0
        for right,c in enumerate(s):
            x=ord(c)-65;counts[x]+=1;max_freq=max(max_freq,counts[x])
            while right-left+1-max_freq>k:
                counts[ord(s[left])-65]-=1;left+=1
            best=max(best,right-left+1)
        return best

class Solution {
    public int characterReplacement(String s,int k) {
        int[]cnt=new int[26];int left=0,maxFreq=0,best=0;
        for(int right=0;right<s.length();right++){int x=s.charAt(right)-'A';maxFreq=Math.max(maxFreq,++cnt[x]);
            while(right-left+1-maxFreq>k)cnt[s.charAt(left++)-'A']--;
            best=Math.max(best,right-left+1);
        }return best;
    }
}

class Solution:
    def construct(self, grid: list[list[int]]):
        def build(r,c,size):
            value=grid[r][c];uniform=True
            for i in range(r,r+size):
                for j in range(c,c+size):
                    if grid[i][j]!=value:uniform=False;break
                if not uniform:break
            if uniform:return Node(bool(value),True)
            half=size//2
            return Node(True,False,build(r,c,half),build(r,c+half,half),build(r+half,c,half),build(r+half,c+half,half))
        return build(0,0,len(grid))

class Solution {
    private int[][] grid;
    public Node construct(int[][] grid) { this.grid=grid;return build(0,0,grid.length); }
    private Node build(int r,int c,int size) {
        int v=grid[r][c];boolean same=true;
        for(int i=r;i<r+size&&same;i++)for(int j=c;j<c+size;j++)if(grid[i][j]!=v){same=false;break;}
        if(same)return new Node(v==1,true);
        int h=size/2;
        return new Node(true,false,build(r,c,h),build(r,c+h,h),build(r+h,c,h),build(r+h,c+h,h));
    }
}

