class Solution:
    def levelOrder(self, root):
        if not root:return []
        q=deque([root]);out=[]
        while q:
            level=[]
            for _ in range(len(q)):
                node=q.popleft();level.append(node.val);q.extend(node.children or [])
            out.append(level)
        return out

import java.util.*;
class Solution {
    public List<List<Integer>> levelOrder(Node root) {
        List<List<Integer>>out=new ArrayList<>();if(root==null)return out;Queue<Node>q=new ArrayDeque<>();q.offer(root);
        while(!q.isEmpty()){int size=q.size();List<Integer>level=new ArrayList<>();for(int i=0;i<size;i++){Node x=q.poll();level.add(x.val);if(x.children!=null)q.addAll(x.children);}out.add(level);}return out;
    }
}

class Solution:
    def flatten(self, head):
        if not head:return head
        stack=[];cur=head
        while cur:
            if cur.child:
                if cur.next:stack.append(cur.next)
                cur.next=cur.child;cur.child.prev=cur;cur.child=None
            elif not cur.next and stack:
                nxt=stack.pop();cur.next=nxt;nxt.prev=cur
            cur=cur.next
        return head

import java.util.*;
class Solution {
    public Node flatten(Node head) {
        if(head==null)return null;Deque<Node>stack=new ArrayDeque<>();Node cur=head;
        while(cur!=null){if(cur.child!=null){if(cur.next!=null)stack.push(cur.next);cur.next=cur.child;cur.child.prev=cur;cur.child=null;}
            else if(cur.next==null&&!stack.isEmpty()){Node next=stack.pop();cur.next=next;next.prev=cur;}cur=cur.next;}
        return head;
    }
}

