class Solution:
    def minMutation(self, startGene: str, endGene: str, bank: list[str]) -> int:
        if startGene==endGene:return 0
        allowed=set(bank)
        if endGene not in allowed:return -1
        q=deque([(startGene,0)]);seen={startGene};letters="ACGT"
        while q:
            gene,d=q.popleft()
            for i in range(len(gene)):
                for c in letters:
                    nxt=gene[:i]+c+gene[i+1:]
                    if nxt==endGene:return d+1
                    if nxt in allowed and nxt not in seen:seen.add(nxt);q.append((nxt,d+1))
        return -1

import java.util.*;
class Solution {
    public int minMutation(String startGene,String endGene,String[] bank) {
        if(startGene.equals(endGene))return 0;Set<String>allowed=new HashSet<>(Arrays.asList(bank));if(!allowed.contains(endGene))return -1;
        Queue<String>q=new ArrayDeque<>();Map<String,Integer>d=new HashMap<>();q.offer(startGene);d.put(startGene,0);char[]bases={'A','C','G','T'};
        while(!q.isEmpty()){String g=q.poll();int dist=d.get(g);char[]a=g.toCharArray();
            for(int i=0;i<a.length;i++){char old=a[i];for(char b:bases){a[i]=b;String next=new String(a);if(next.equals(endGene))return dist+1;if(allowed.contains(next)&&!d.containsKey(next)){d.put(next,dist+1);q.offer(next);}}a[i]=old;}
        }return -1;
    }
}

class Solution:
    def eraseOverlapIntervals(self, intervals: list[list[int]]) -> int:
        intervals.sort(key=lambda x:x[1]);kept=0;end=float('-inf')
        for start,finish in intervals:
            if start>=end:kept+=1;end=finish
