import java.util.*;
class Solution {
    public int eraseOverlapIntervals(int[][] intervals) {
        Arrays.sort(intervals,Comparator.comparingInt(a->a[1]));int kept=0;long end=Long.MIN_VALUE;
        for(int[]x:intervals)if(x[0]>=end){kept++;end=x[1];}
        return intervals.length-kept;
    }
}

from collections import defaultdict
class Solution:
    def pathSum(self, root, targetSum: int) -> int:
        prefix=defaultdict(int);prefix[0]=1
        def dfs(node,total):
            if not node:return 0
            total+=node.val;count=prefix[total-targetSum]
            prefix[total]+=1
            count+=dfs(node.left,total)+dfs(node.right,total)
            prefix[total]-=1
            return count
        return dfs(root,0)

import java.util.*;
class Solution {
    private Map<Long,Integer> prefix;private int target;
    public int pathSum(TreeNode root,int targetSum){prefix=new HashMap<>();prefix.put(0L,1);target=targetSum;return dfs(root,0L);}
    private int dfs(TreeNode n,long sum){if(n==null)return 0;sum+=n.val;int count=prefix.getOrDefault(sum-target,0);prefix.put(sum,prefix.getOrDefault(sum,0)+1);count+=dfs(n.left,sum)+dfs(n.right,sum);prefix.put(sum,prefix.get(sum)-1);return count;}
}

class Solution:
    def findAnagrams(self, s: str, p: str) -> list[int]:
        if len(p)>len(s):return []
        need=[0]*26;win=[0]*26
        for c in p:need[ord(c)-97]+=1
        out=[];k=len(p)
        for i,c in enumerate(s):
            win[ord(c)-97]+=1
            if i>=k:win[ord(s[i-k])-97]-=1
            if i>=k-1 and win==need:out.append(i-k+1)
        return out

import java.util.*;
class Solution {
    public List<Integer> findAnagrams(String s,String p) {
        List<Integer>out=new ArrayList<>();if(p.length()>s.length())return out;int[]need=new int[26],win=new int[26];for(char c:p.toCharArray())need[c-'a']++;
        int k=p.length();for(int i=0;i<s.length();i++){win[s.charAt(i)-'a']++;if(i>=k)win[s.charAt(i-k)-'a']--;if(i>=k-1&&Arrays.equals(need,win))out.add(i-k+1);}return out;
    }
}

class Solution:
    def findKthNumber(self, n: int, k: int) -> int:
        def steps(prefix,next_prefix):
            total=0
            while prefix<=n:
                total+=min(n+1,next_prefix)-prefix
                prefix*=10;next_prefix*=10
            return total
        curr=1;k-=1
        while k>0:
            count=steps(curr,curr+1)
            if count<=k:curr+=1;k-=count
            else:curr*=10;k-=1
        return curr

class Solution {
    public int findKthNumber(int n,int k) {
        long curr=1;k--;
        while(k>0){long count=steps(n,curr,curr+1);if(count<=k){curr++;k-=count;}else{curr*=10;k--;}}
        return (int)curr;
    }
    private long steps(long n,long first,long next){long total=0;while(first<=n){total+=Math.min(n+1,next)-first;first*=10;next*=10;}return total;}
}

class Solution:
    def arrangeCoins(self, n: int) -> int:
        lo,hi=0,n
        while lo<hi:
            mid=(lo+hi+1)//2
            if mid*(mid+1)//2<=n:lo=mid
            else:hi=mid-1
        return lo

class Solution {
    public int arrangeCoins(int n) {
        long lo=0,hi=n;
        while(lo<hi){long mid=(lo+hi+1)/2;if(mid*(mid+1)/2<=n)lo=mid;else hi=mid-1;}
        return (int)lo;
    }
}
